insert into public.plant_archive (latin_name, german_name, category, info_html) values
('Acer pseudoplatanus', 'Bergahorn', 'baum', '<h3>Fun Facts</h3><p>Eine seltene Holzmaserung namens Riegelung, entstanden durch wellenförmige Fasern, tritt nur bei etwa 3% der Bäume auf — ein Stamm damit erzielte in Frankreich über 61.000 Euro</p><p>Unter einem solchen Baum in Graubünden wurde 1424 der "Graue Bund" gegründet, ein Vorläufer des Kantons — die Mitglieder trafen sich dort bis 1870, als ein Sturm den Baum fällte</p><p>Die geflügelten Samen drehen sich beim Fallen etwa 16 Mal pro Sekunde und können so vom Wind über 100 Meter weit getragen werden</p><p>Der Artname bezieht sich auf die Ähnlichkeit der Blätter mit der Platane, regional wird er auch "Milchbaum" genannt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Seifenbaumgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">fünflappig, gesägter Rand</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelbgrün, in hängenden Rispen</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">geflügelte Spaltfrucht (Samara)</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Bergwälder, Schluchtwälder</td></tr></table>'),
('Aesculus hippocastanum', 'Rosskastanie', 'baum', '<h3>Fun Facts</h3><p>Die Osmanen brachten die Samen einst als Pferdefutter und Mittel gegen Pferdehusten mit — für Menschen sind sie trotz der Ähnlichkeit zur Edelkastanie ungenießbar, daher der Name</p><p>Ein Wiener Gesandter brachte sie 1576 aus Konstantinopel nach Europa, vermutlich stammen viele heutige Bäume von genau diesen ersten Samen ab</p><p>Im 18. Jahrhundert testete man ihre Rinde als billigeren Ersatz für die teure Chinarinde gegen Fieber — die Wirkung blieb aber umstritten</p><p>Die kerzenartigen Blütenstände tragen Blüten, deren gelbes Saftmal sich nach der Bestäubung rot färbt — ein Signal an Insekten, dass sich der Besuch dort nicht mehr lohnt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Seifenbaumgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">fingerförmig, 5-7 Fiederblättchen</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß mit gelb-rotem Saftmal</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">halbschattig bis sonnig, nährstoffreiche Böden</td></tr></table>'),
('Betula pendula', 'Hängebirke', 'baum', '<h3>Fun Facts</h3><p>Ihre schlaff hängenden, korkwarzigen Zweige wirken bei Wind wie Schleifpapier und können in die Kronen benachbarter Bäume regelrecht Schneisen schleifen, um sich Licht zu verschaffen</p><p>Aus der destillierten Rinde entsteht Birkenpech, das schon in der Altsteinzeit als Universalklebstoff diente — bis ins Mittelalter blieb es im Gebrauch</p><p>Die weiße Rindenfarbe entsteht durch eingelagertes Betulin, das Licht fast vollständig reflektiert und so vor intensiver Sonneneinstrahlung schützt, besonders im Winter</p><p>Das Holz enthält so viel Terpene, dass es sogar im grünen, frisch geschlagenen Zustand noch brennt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Birkengewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">dreieckig-rautenförmig, lange Spitze</td></tr><tr><td class="merkmal-key">Blattrand</td><td class="merkmal-val">doppelt gesägt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">saure, trockene Böden, Pionierbaum</td></tr></table>'),
('Fagus sylvatica', 'Rotbuche', 'baum', '<h3>Fun Facts</h3><p>Der Name ist eigentlich irreführend, denn das Holz schimmert nur leicht rötlich — die "Weißbuche" dagegen gehört trotz ihres Namens gar nicht zu den Buchen, sondern zu den Birkengewächsen</p><p>Im Nationalpark Kalkalpen in Oberösterreich wurde 2019 eine rund 546 Jahre alte Buche entdeckt, die älteste datierte ihrer Art in Mitteleuropa</p><p>Nach trockenen, heißen Jahren produziert sie besonders viele Früchte auf einmal — ein "Mastjahr", das Mäuse und Wildschweine satt frisst, aber trotzdem genug Samen zum Keimen übrig lässt</p><p>Lange galt ihr Holz als minderwertig, bis teerölimprägnierte Eisenbahnschwellen daraus Jahrzehnte hielten — ab 1830 nutzte Michael Thonet das biegsame Holz für seine berühmten Bugholzstühle</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Buchengewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">eiförmig, wellig-schwach gezähnt</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">Bucheckern, roh leicht giftig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">nährstoffreiche, lehmige Böden</td></tr></table>'),
('Fraxinus excelsior', 'Gemeine Esche', 'baum', '<h3>Fun Facts</h3><p>Trägt über 60 deutsche Trivialnamen, darunter "Sperlingszungenbaum" — benannt nach den flachen, geflügelten Früchten, früher "Vogelzunge" genannt</p><p>In der nordischen Mythologie gilt sie als Weltenbaum Yggdrasil, und der erste Mensch Ask soll von den Göttern aus genau diesem Holz geformt worden sein</p><p>Seit den frühen 1990ern breitet sich in Europa ein Pilz aus, der ganze Bestände bedroht — in Dänemark fielen ihm bis 2013 über 95% aller Bäume dieser Art zum Opfer</p><p>Als einzige Art ihrer Pflanzenfamilie wird sie nicht von Insekten, sondern vom Wind bestäubt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Ölbaumgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">unpaarig gefiedert, 9-15 Fiederblättchen</td></tr><tr><td class="merkmal-key">Blattrand</td><td class="merkmal-val">gesägt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">tiefgründige, frische Böden, Auwälder</td></tr></table>'),
('Juglans regia', 'Walnuss', 'baum', '<h3>Fun Facts</h3><p>Der deutsche Name geht auf "welsche Nuss" zurück — eine Nuss, die über den romanischen Sprachraum nach Mitteleuropa kam, der Gattungsname Juglans bedeutet wörtlich "Eichel des Jupiter"</p><p>Unter diesen Bäumen wächst kaum etwas: Die Blätter geben Stoffe ab, aus denen beim Abbau Juglon entsteht, das Keimung und Wachstum vieler Nachbarpflanzen hemmt</p><p>Ihr Holz gilt als das wertvollste des mitteleuropäischen Waldes und wurde dadurch über Jahrhunderte stark dezimiert</p><p>Ausgerechnet das waldarme Kirgisistan beherbergt die größten Bestände weltweit — im Tian-Shan-Gebirge werden die Bäume dort bis 30 Meter hoch und über 150 Jahre alt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Walnussgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">unpaarig gefiedert, meist 7 Blättchen</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">aromatisch-harzig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">tiefgründige, nährstoffreiche Lehmböden</td></tr></table>'),
('Picea abies', 'Gemeine Fichte', 'baum', '<h3>Fun Facts</h3><p>In Schweden wurde unter einem Exemplar ein Wurzelsystem entdeckt, das auf rund 9.550 Jahre datiert und genetisch identisch mit dem darüber wachsenden Baum ist — ein uralter Klon</p><p>1874 synthetisierte ein deutscher Chemiker erstmals künstliches Vanillin, gewonnen aus dem Saft heimischer Bäume dieser Art</p><p>Nordamerikanische Ureinwohner brauten aus ihren Sprossen ein haltbares Getränk, das Seefahrer später gegen Skorbut auf langen Reisen übernahmen — daraus entstand das "Spruce Beer"</p><p>Die meisten im Wald gefundenen "Tannenzapfen" stammen gar nicht von der Tanne, sondern von diesem Baum — denn echte Tannenzapfen fallen nie als Ganzes zu Boden</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Kieferngewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">Nadeln vierkantig, 1-2 cm, rundum am Zweig</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">hängender Zapfen, 10-15 cm, fällt ganz ab</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">kühl-feuchte Gebirgslagen</td></tr></table>'),
('Pinus sylvestris', 'Waldkiefer', 'baum', '<h3>Fun Facts</h3><p>Zur Hauptblütezeit verteilt sie so viel gelben Pollen, dass er sich als sichtbarer "Schwefelregen" niederschlägt — selbst in Großstädten wie Berlin</p><p>Nach der Reaktorkatastrophe von Tschernobyl fanden Forscher bei den dort wachsenden Bäumen eine verstärkte DNA-Methylierung, möglicherweise eine Anpassung an die Strahlung</p><p>Auf einer alten Schildmauer einer Burgruine im Odenwald wurzelt ein über 300 Jahre altes Exemplar, das trotz der kargen Mauerspalte rund sieben Meter hoch wurde</p><p>Ihre Zapfen funktionieren wie natürliche Wetterfühler: Bei Feuchtigkeit schließen sie sich, bei Trockenheit spreizen sie sich und entlassen die Samen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Kieferngewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">Nadeln zu zweit, 4-7 cm, blaugrün, gedreht</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">eiförmig-kegeliger Zapfen, bis 8 cm</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">nährstoffarme, trockene Sandböden</td></tr></table>'),
('Quercus robur', 'Stieleiche', 'baum', '<h3>Fun Facts</h3><p>Ihre Eicheln hängen in Büscheln von drei bis fünf Stück an langen Stielen — namensgebend für "Stiel-Eiche"</p><p>Einzelne Exemplare werden 500 bis 1000 Jahre alt, in seltenen Fällen sogar rund 1400 Jahre</p><p>In guten Jahren trieb man früher Schweine zur Mast in diese Wälder, woher das Sprichwort "Auf den Eichen wächst der beste Schinken" stammt</p><p>Eichelhäher vergraben Eicheln als Wintervorrat und vergessen viele davon — diese "Hähersaat" ist bis heute einer der Hauptwege, wie sich der Baum von selbst ausbreitet</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Buchengewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">gelappt, kurzgestielt</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">lang gestielte Eichel, in Gruppen</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">feuchte Niederungen, Auenwälder</td></tr></table>'),
('Salix alba', 'Silberweide', 'baum', '<h3>Fun Facts</h3><p>Hildegard von Bingen empfahl im 12. Jahrhundert Tee aus ihrer Rinde gegen Fieber und Rheuma — das enthaltene Salicin ist ein Vorläuferstoff des heutigen Aspirin-Wirkstoffs</p><p>Ihr Kernholz ist kaum gegen Fäulnis geschützt, daher sind alte Exemplare oft hohl — die Höhlen dienen Tieren als Unterschlupf oder füllen sich mit Humus für andere Pflanzen</p><p>Durch regelmäßiges Zurückschneiden entstanden früher "Kopfweiden", deren Ruten als Flechtmaterial für Körbe und Fachwerk-Ausfachungen dienten</p><p>Ihre Zweige bewurzeln sich bei Bodenkontakt sehr leicht — als Teil der Weichholzaue hilft sie zudem, Ufer zu stabilisieren und Hochwasser zu mildern</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Weidengewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">schmal-lanzettlich, fein gesägt</td></tr><tr><td class="merkmal-key">Behaarung</td><td class="merkmal-val">Unterseite dicht, silbrig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Ufer, Auwälder, periodisch überflutet</td></tr></table>'),
('Tilia platyphyllos', 'Sommerlinde', 'baum', '<h3>Fun Facts</h3><p>Kann über 1000 Jahre alt werden: Sterben innere Teile des alten Stammes ab, wachsen von oben neue Wurzeln nach unten und bilden eine junge Krone — der Baum verjüngt sich quasi von innen</p><p>Markierte in vielen deutschen Dörfern den Mittelpunkt, der zugleich Versammlungsort und Gerichtsstätte war</p><p>In manchen Orten baute man einen Tanzboden direkt in die Krone, erhaltene Beispiele sind die Tanzlinden von Limmersdorf und Galenbeck</p><p>"Zur Linde" ist mit über 1000 Nennungen der häufigste Gasthausname in ganz Deutschland</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Malvengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelblich-weiß</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">herzförmig, schief, gesägt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Gebirgslagen, Schluchtwälder, Alleen</td></tr></table>'),
('Ulmus minor', 'Feldulme', 'baum', '<h3>Fun Facts</h3><p>Kann über 500 Jahre alt, über 35 Meter hoch und an der Basis über 2 Meter dick werden</p><p>Das "Ulmensterben" wird von Schlauchpilzen verursacht, die vor allem ältere Bäume befallen — sie treiben danach oft wieder aus, weshalb man heute fast nur junge Exemplare sieht</p><p>Resistente Zuchtsorten sind nach zwei Phytopathologinnen benannt, die an der Aufklärung der Pilzkrankheit beteiligt waren</p><p>Ihre Blätter dienen seltenen Schmetterlingsarten wie dem Großen Fuchs als Futterpflanze und wurden im Mittelalter auch als Schafsfutter genutzt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Ulmengewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">eiförmig, asymmetrischer Grund</td></tr><tr><td class="merkmal-key">Blattrand</td><td class="merkmal-val">einfach bis doppelt gesägt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Auwälder, Mischwälder, kalkliebend</td></tr></table>'),
('Achillea millefolium', 'Schafgarbe', 'wiese', '<h3>Fun Facts</h3><p>Der Gattungsname geht auf den griechischen Helden Achilles zurück, der sie der Legende nach vom Kentauren Chiron kannte und damit eine schwer heilende Wunde behandelte</p><p>In Nordamerika und China wird sie seit rund 4000 Jahren als Heilpflanze genutzt — den Germanen galt sie sogar als Schutz gegen fast alle Krankheiten</p><p>Aus ihren trockenen Stängeln fertigt man bis heute die Stäbchen für das traditionelle chinesische Schafgarbenorakel, das mit dem I Ging verbunden ist</p><p>Ihre Blüten kommen auch in Dampfbädern zur Gesichtspflege zum Einsatz, als Bittertee wird die blühende Pflanze bei Verdauungsstörungen genutzt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß bis rosa</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">fein gefiedert</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">aromatisch</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Anthriscus sylvestris', 'Wiesen-Kerbel', 'wiese', '<h3>Fun Facts</h3><p>Blüht unter allen mitteleuropäischen Doldenblütlern am frühesten, oft schon ab April, und prägt dann zusammen mit dem Scharfen Hahnenfuß stark gedüngte Wiesen</p><p>Bei Berührung kann er phototoxische Hautreaktionen auslösen, ähnlich wie der bekanntere Riesen-Bärenklau, nur deutlich schwächer</p><p>Er wird leicht mit dem sehr giftigen Gefleckten Schierling verwechselt, daher Vorsicht beim Sammeln ähnlich aussehender Doldenblütler</p><p>Sein Artname bedeutet "im Wald wachsend", obwohl er tatsächlich vor allem auf Wiesen vorkommt — ein Name, der schon Linné bei der Erstbeschreibung irreführte</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Doldenblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">fein gefiedert</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wegränder, Wiesen</td></tr></table>'),
('Bellis perennis', 'Gänseblümchen', 'wiese', '<h3>Fun Facts</h3><p>Was wie eine einzelne Blüte aussieht, ist tatsächlich ein Körbchen aus über hundert Einzelblüten — es richtet sich nach der Sonne aus und schließt sich abends sowie bei schlechtem Wetter</p><p>In England heißt sie "Day''s Eye" ("Auge des Tages"), woraus sich vermutlich der englische Name Daisy entwickelte</p><p>Königsgräber in Ur aus dem dritten Jahrtausend v. Chr. enthielten einen goldenen Kopfschmuck, der mit genau diesem Blütenmuster verziert war</p><p>Ihre Knospen schmecken roh leicht nussig und wurden sauer eingelegt früher gern als Kapernersatz verwendet</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß mit gelber Mitte</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Rasen</td></tr></table>'),
('Campanula patula', 'Wiesen-Glockenblume', 'wiese', '<h3>Fun Facts</h3><p>Wie alle Glockenblumen reifen ihre Staubblätter vor den Narben — ein Trick, der Selbstbestäubung weitgehend verhindert und Bienen zu den eigentlichen Bestäubern macht</p><p>Ihr Vorkommen gilt Botanikern als verlässliches Zeichen für nährstoffreiche Wiesengesellschaften</p><p>Der Artname bedeutet "abstehend" und bezieht sich auf die weit ausgebreiteten Kronzipfel ihrer Blüten</p><p>Regional trug sie zahlreiche Volksnamen wie "Fingerhuat" in der Schweiz oder "Sternblum" im Salzburger Land</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Glockenblumengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">violett-blau</td></tr><tr><td class="merkmal-key">Blütenform</td><td class="merkmal-val">glockig, nickend</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">magere Wiesen</td></tr></table>'),
('Cardamine pratensis', 'Wiesen-Schaumkraut', 'wiese', '<h3>Fun Facts</h3><p>Ihre reifen Schoten reißen explosionsartig auf und können die Samen bis zu 2,4 Meter weit verstreuen — eine in Europas Flora eher seltene Ausbreitungsmethode</p><p>Berührt ein Grundblatt feuchten Boden, bildet es dort Brutknospen, die eigene Wurzeln schlagen und zu neuen Pflanzen heranwachsen — eine Vermehrung ganz ohne Samen</p><p>Ist zusammen mit der Knoblauchsrauke die bevorzugte Raupenpflanze des Aurorafalters, der seine Eier meist direkt an die Blütenstiele legt</p><p>2006 wurde sie zur Blume des Jahres gewählt, in manchen Bundesländern gilt sie wegen des Rückgangs feuchter Wiesen inzwischen als gefährdet</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Kreuzblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">hellviolett bis weiß</td></tr><tr><td class="merkmal-key">Anzahl Kronblätter</td><td class="merkmal-val">4</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">feuchte Wiesen</td></tr></table>'),
('Centaurea jacea', 'Wiesen-Flockenblume', 'wiese', '<h3>Fun Facts</h3><p>Gilt vielen Agrarprogrammen als verlässliche Zeigerpflanze für artenreiche, extensiv genutzte Wiesen — ihr Vorkommen zeigt gute Grünlandqualität an</p><p>Es gibt zwittrige, rein männliche und rein weibliche Exemplare — ihre Blüten reifen zudem nacheinander und verhindern so Selbstbefruchtung</p><p>Der Blütenbesuch durch Bienen, Hummeln und Schmetterlinge erreicht um 15 Uhr seinen Höhepunkt</p><p>Bildet leicht fruchtbare Mischformen mit verwandten Flockenblumen-Arten, was ihre genaue Unterart-Einteilung bis heute erschwert</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">rosa-violett</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Brachen</td></tr></table>'),
('Galium mollugo', 'Wiesen-Labkraut', 'wiese', '<h3>Fun Facts</h3><p>Enthält ein Enzym, das Milch dicklegen kann — ähnlich dem Lab aus dem Kälbermagen, das bei der Käseherstellung genutzt wird und der Pflanze ihren Namen gab</p><p>Ihre Wurzeln dienten früher zum Färben von Textilien in Rot, ganz ähnlich wie beim verwandten Färberkrapp</p><p>Ihre reifen Samen ergeben geröstet einen aromatischen Kaffee-Ersatz</p><p>Sie bildet zusammen mit einer sehr ähnlichen, häufigeren Verwandten eine schwer zu unterscheidende Artengruppe, die Botaniker oft verwechseln</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Rötegewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Blattstellung</td><td class="merkmal-val">quirlig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Geranium pratense', 'Wiesen-Storchschnabel', 'wiese', '<h3>Fun Facts</h3><p>Lösen sich die Fruchtfächer von der Mittelsäule, werden die Samen katapultartig bis über 2 Meter weit fortgeschleudert</p><p>Ihre Blätter richten sich dank spezieller Blattgelenke gezielt zum stärksten Lichteinfall aus, ein Vorgang namens Photonastie</p><p>Der Nektar liegt geschützt unter einem Haarkranz, der aufwärtskriechende Insekten gezielt abhalten soll, ohne den eigentlichen Bestäubern den Zugang zu verwehren</p><p>Kann sich an größeren Nachbarpflanzen abstützen und so quasi als Spreizklimmer höher hinaus wachsen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Storchschnabelgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">violettblau</td></tr><tr><td class="merkmal-key">Anzahl Kronblätter</td><td class="merkmal-val">5</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Heracleum sphondylium', 'Wiesen-Bärenklau', 'wiese', '<h3>Fun Facts</h3><p>Ihre gelappten, behaarten Blätter sollen an Tierpfoten erinnern — daher der Name "Bärenklau", auch "Bärentappe" genannt</p><p>Im Mittelalter gehörten junge Teile zum Borschtsch, dessen Name vermutlich auf den slawischen Namen genau dieser Pflanze zurückgeht</p><p>In Neutralalkohol eingelegt färben ihre unreifen Samen den Ansatz intensiv grün, ähnlich wie beim Absinth</p><p>Ihre Furocumarine machen die Haut bei UV-Licht empfindlicher — beim Schälen der Stängel sollte man deshalb Handschuhe tragen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Doldenblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weißlich</td></tr><tr><td class="merkmal-key">Blütenform</td><td class="merkmal-val">Dolde</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Waldränder</td></tr></table>'),
('Leucanthemum vulgare', 'Wiesen-Margerite', 'wiese', '<h3>Fun Facts</h3><p>Was wie eine einzelne Blüte aussieht, besteht aus 300 bis 400 gelben Röhrenblüten in der Mitte und weißen Zungenblüten, die nur als Schauapparat für Insekten dienen</p><p>Im Mittelalter hieß sie "Blume des heiligen Johannes" und wurde deshalb auch Johannisblume genannt</p><p>Zu Beginn des 20. Jahrhunderts wurden an eigenen "Margeritentagen" Straßen damit geschmückt und künstliche Nachbildungen für wohltätige Zwecke verkauft</p><p>Obwohl nicht giftig, können enthaltene Polyacetylene unter Sonneneinstrahlung Hautreaktionen auslösen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß mit gelber Mitte</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Medicago lupulina', 'Hopfenklee', 'wiese', '<h3>Fun Facts</h3><p>Der Artname bezieht sich auf den Hopfen, weil ihre Blütenstände entfernt an Hopfendolden erinnern — eine beliebte Deutung als "wölfchenartig" ist dagegen schlicht falsch</p><p>Ihre Staubblätter schnellen beim ersten Insektenbesuch aus dem Schiffchen heraus und drücken sich an den Bauch des Besuchers, um den Pollen gezielt zu übertragen</p><p>Nach der Blüte fällt die Krone schnell ab, sodass die schneckenartig gedrehten, schwarzen Hülsen schon lange vor der Reife gut sichtbar sind</p><p>In Süddeutschland ist sie bereits seit der Bronzezeit nachgewiesen und heute durch Saatgutverunreinigung fast weltweit verbreitet</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Schmetterlingsblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelb</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">schwarze, nierenförmige Hülse</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Plantago lanceolata', 'Spitzwegerich', 'wiese', '<h3>Fun Facts</h3><p>Der Name "Wegerich" stammt aus dem Althochdeutschen, wo "rīh" König bedeutet — derselbe Wortteil steckt auch in Namen wie Friedrich oder Dietrich</p><p>Ihre Blätter sind offiziell anerkannt bei Entzündungen der Atemwege, zerrieben auf Insektenstiche gelegt wirken sie zudem kühlend und schmerzlindernd</p><p>Nach beiden Weltkriegen und in Krisenzeiten galt Salat aus dieser wilden Pflanze als beliebter Ersatz für teures Blattgemüse</p><p>Ihre Wurzeln bilden natürliche Nitrifikationshemmer, die Stickstoff im Boden länger verfügbar halten — Forscher testen sie deshalb als Untersaat im Maisanbau</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Wegerichgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">lanzettlich, längsrippig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Plantago major', 'Breitwegerich', 'wiese', '<h3>Fun Facts</h3><p>Wächst trittfest an stark begangenen Stellen und in Pflasterritzen — indigene Völker Nordamerikas nannten sie nach ihrer Ankunft mit europäischen Siedlern treffend "Fußstapfen des weißen Mannes"</p><p>Jeder Blütenstand produziert 2 bis 3 Millionen Pollenkörner, die der Wind verbreitet — ein wichtiger Auslöser von Heuschnupfen</p><p>Ihre Wurzel kann bis zu 80 cm lang werden, wodurch sie selbst auf stark verdichteten Böden noch gedeiht</p><p>Junge, zarte Blätter eignen sich als Salat, ältere werden zäh und landen am besten im Eintopf</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Wegerichgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">breit-oval, längsrippig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wege, Trittrasen</td></tr></table>'),
('Ranunculus acris', 'Scharfer Hahnenfuß', 'wiese', '<h3>Fun Facts</h3><p>Ihre glänzend goldgelben "Blütenblätter" sind botanisch eigentlich umgewandelte Staubblätter mit einer Nektardrüse an der Basis</p><p>Frisch ist die ganze Pflanze giftig und kann Hautblasen verursachen — getrocknet im Heu wandelt sich der Giftstoff aber in eine deutlich schwächere Form um, weshalb Heu für Vieh unbedenklich ist</p><p>Ihre winzigen, nur 1,5 mg leichten Samen segeln im Wind wie kleine Flieger und werden zusätzlich von Rindern über den Darm verbreitet</p><p>Im Volksmund auch "Butterblume" genannt, was allerdings genauso für andere gelbe Wiesenblumen gilt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Hahnenfußgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelb, glänzend</td></tr><tr><td class="merkmal-key">Anzahl Kronblätter</td><td class="merkmal-val">5</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Weiden</td></tr></table>'),
('Taraxacum officinale', 'Löwenzahn', 'wiese', '<h3>Fun Facts</h3><p>Die haarigen Flugschirme ihrer Früchte gaben ihr den Namen Pusteblume, andere Mundartnamen wie "Bettnässer" verweisen dagegen auf ihre harntreibende Wirkung</p><p>Manche Pflanzen bilden Samen völlig ohne Befruchtung und erzeugen so genetisch identische Klone — trotzdem produzieren sie weiterhin Nektar, obwohl sie gar keine Bestäuber mehr benötigen</p><p>Ihre im Herbst geernteten, inulinreichen Wurzeln wurden geröstet in den Nachkriegsjahren als beliebter Kaffee-Ersatz genutzt</p><p>Für nur ein Kilogramm Honig muss ein Bienenvolk über 100.000 ihrer Blüten besuchen — als früher Frühlingsblüher ist sie dennoch eine wichtige erste Bienenweide im Jahr</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelb</td></tr><tr><td class="merkmal-key">Milchsaft</td><td class="merkmal-val">vorhanden</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Wegränder</td></tr></table>'),
('Trifolium pratense', 'Rotklee', 'wiese', '<h3>Fun Facts</h3><p>Regional trägt sie Namen wie "Fleischklee" oder "Herrgottsfleisch" wegen ihrer dunkelrosa Blütenfarbe</p><p>Nur langrüsselige Hummeln kommen an den Nektar am Grund der 9-10 mm tiefen Blütenröhre, Honigbienen sammeln an ihr meist nur Pollen</p><p>Für den kommerziellen Rotklee-Anbau musste Neuseeland eigens Hummeln importieren, da die passenden Bestäuber dort ursprünglich fehlten</p><p>Als Gründünger und Kleegras verbessert sie durch Knöllchenbakterien an den Wurzeln den Stickstoffgehalt des Bodens, junge Blätter eignen sich auch für Salate und Kräutermischungen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Hülsenfrüchtler (Schmetterlingsblütler)</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">rot bis dunkelrosa, in kugeligen Köpfchen</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">dreiteilig, mit hellerem Fleck in der Blattmitte</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Fettwiesen, Felder, lichte Wälder</td></tr></table>'),
('Trifolium repens', 'Weißklee', 'wiese', '<h3>Fun Facts</h3><p>Eine Studie von 2022 untersuchte über 110.000 Pflanzen aus 160 Städten und fand in Innenstädten weniger Blausäure als im Umland, vermutlich weil dort weniger Pflanzenfresser leben</p><p>Vierblättrige Kleeblätter sind bei Wildpflanzen selten, weil die Anlage dafür im Laufe der Evolution rezessiv geworden ist</p><p>Ein einzelner Trieb kann unter guten Bedingungen in einem Sommer mehrere Quadratmeter bedecken, da die kriechenden Stängel an jedem Knoten neue Wurzeln bilden</p><p>Knöllchenbakterien an den Wurzeln liefern dem Boden Stickstoff, gleichzeitig zählt sie als wichtige Bienentrachtpflanze mit reichem Nektarangebot</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Hülsenfrüchtler (Schmetterlingsblütler)</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß, nach dem Verblühen hellbraun</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">dreizählig gefingert, oft mit hellerer Querbinde</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Weiden, Wegränder, Rasenflächen</td></tr></table>'),
('Vicia cracca', 'Vogelwicke', 'wiese', '<h3>Fun Facts</h3><p>Die Ranken an den Blattspitzen tasten kreisend ihre Umgebung ab und reagieren auf Berührung, um sich an Halmen und Nachbarpflanzen festzuhalten</p><p>Hummeln beißen oft seitlich ein Loch in die Blüte, um ohne Bestäubung an den Nektar zu kommen, Honigbienen nutzen diese Löcher anschließend ebenfalls</p><p>Die schwarzen Hülsen speichern Wärme und trocknen aus, bis sie plötzlich aufspringen und die Samen ein bis zwei Meter weit herausschleudern</p><p>Wie andere Wicken bildet sie Wurzelknöllchen mit Bakterien, die Luftstickstoff für die Pflanze nutzbar machen, und wurzelt dabei recht tief</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Hülsenfrüchtler (Schmetterlingsblütler)</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">blauviolett bis purpurn, in einseitigen Trauben</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">gefiedert mit 8-12 Fiederpaaren, endet in verzweigter Ranke</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">sonnige Wiesen, Weiden, Feldraine, Brachflächen</td></tr></table>'),
('Aegopodium podagraria', 'Giersch', 'kraut', '<h3>Fun Facts</h3><p>Der Gattungsname bedeutet "ziegenfüßig" — vermutlich wegen der Blattscheiden-Reste am Rhizom, die an Ziegenklauen erinnern, nicht wegen der Blattform selbst</p><p>Der Artname verweist auf die jahrhundertelange Nutzung als Volksmedizin gegen Gicht, daher auch die Namen "Podagrakraut" oder "Zipperleinskraut"</p><p>In beiden Weltkriegen sicherte das vitaminreiche Wildgemüse vielen Menschen die Versorgung mit Vitamin C, wenn anderes Gemüse knapp war</p><p>Seine brüchigen, weißen Ausläufer wurzeln bis 50 cm tief und können binnen wenigen Jahren ganze Beete erobern — selbst die meisten Herbizide wirken gegen ihn kaum</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Doldenblütler</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">doppelt dreizählig gefiedert</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">schattige Gärten, Waldränder</td></tr></table>'),
('Allium schoenoprasum', 'Schnittlauch', 'kraut', '<h3>Fun Facts</h3><p>Der Artname bedeutet sinngemäß "Binsen-Lauch" aus dem Griechischen — regional trägt sie auch Namen wie "Jakobszwiebel"</p><p>Kommt rund um den gesamten Nordpol verbreitet vor und wächst im Himalaya sogar bis in knapp 4760 Meter Höhe</p><p>Ihr typisches Aroma entsteht erst beim enzymatischen Abbau bestimmter Schwefelverbindungen, deshalb verliert sie beim Trocknen deutlich an Geschmack und wird meist frisch oder gefroren verwendet</p><p>Für viele Haustiere ist sie wie andere Lauchgewächse giftig, obwohl sie für Menschen ein beliebtes Gewürz ist</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lauchgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">violett bis purpurrot</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">röhrenförmig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">feuchte, nährstoffreiche Böden</td></tr></table>'),
('Allium ursinum', 'Bärlauch', 'kraut', '<h3>Fun Facts</h3><p>Karl der Große listete ihn in seiner Landgüterverordnung ausdrücklich unter den anzupflanzenden Nutzpflanzen auf — im Mittelalter galt er sogar als "Herba Salutaris" mit unheilabwehrenden Kräften</p><p>Alle Pflanzenteile sind essbar, sogar aus den Blütenknospen lassen sich eingelegt "Bärlauchkapern" machen — am besten roh verwendet, da Hitze das typische Aroma verändert</p><p>Unerfahrene Sammler verwechseln ihn immer wieder mit Maiglöckchen, Herbstzeitlose oder Aronstab — alle drei sind hochgiftig und haben schon zu tödlichen Vergiftungen geführt</p><p>Trotz seiner Häufigkeit gibt es organisierten Diebstahl: 2024 stellte die Polizei in einem einzigen Fall fast 2,5 Tonnen gestohlenen Bärlauch sicher</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lauchgewächse</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">knoblauchartig</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">lanzettlich, längsrippig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">schattige Auwälder</td></tr></table>'),
('Glechoma hederacea', 'Gundermann', 'kraut', '<h3>Fun Facts</h3><p>Bevor der Hopfenanbau sich durchsetzte, nutzte man ihre Bitterstoffe, um Bier haltbar zu machen und zu würzen — ein echter Vorläufer des Hopfens</p><p>Bei der Käseherstellung diente sie früher sogar als pflanzlicher Ersatz für tierisches Lab, das Enzym zum Gerinnen der Milch</p><p>In der Walpurgisnacht band man sie zu Kränzen, durch die man angeblich Hexen erkennen konnte — schon Hildegard von Bingen erwähnte die Pflanze in ihren Schriften</p><p>Ihr Name geht vermutlich auf ein althochdeutsches Wort für Geschwür zurück und verweist auf ihre frühere Nutzung als Wundkraut</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lippenblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">blauviolett</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">nierenförmig gekerbt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wiesen, Gärten, Hecken</td></tr></table>'),
('Hypericum perforatum', 'Johanniskraut', 'kraut', '<h3>Fun Facts</h3><p>Schon das Lorscher Arzneibuch aus dem Jahr 795 empfiehlt sie bei Melancholie, was man heute als Depression verstehen würde — diese Anwendung ist bis heute anerkannt</p><p>Zerreibt man ihre Knospen, hinterlässt der rote Farbstoff Hypericin Flecken auf den Fingern, daher der Volksname "Herrgottsblut"</p><p>Derselbe Farbstoff macht die Haut lichtempfindlicher — Weidetiere, die größere Mengen gefressen haben, können bei Sonne entzündete Hautstellen bekommen, bekannt als "Hartheukrankheit"</p><p>Hält man ein Blatt gegen das Licht, erscheinen winzige helle Punkte: durchscheinende Öldrüsen, die der Pflanze ihren Artnamen "durchlöchert" gaben</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Johanniskrautgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelb</td></tr><tr><td class="merkmal-key">Anzahl Kronblätter</td><td class="merkmal-val">5</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wegränder, Waldränder, Magerwiesen</td></tr></table>'),
('Lamium album', 'Weiße Taubnessel', 'kraut', '<h3>Fun Facts</h3><p>Trägt zwar "Nessel" im Namen, hat aber gar keine Brennhaare — nur die Blattform ähnelt der echten Brennnessel, botanisch ist sie mit ihr kaum verwandt</p><p>Ein Hektar ihrer Blüten kann Honigbienen bis zu 190 kg Honig pro Saison liefern, bestäubt wird sie aber vor allem von langzüngigen Hummeln, die als einzige bis zum tiefsitzenden Nektar reichen</p><p>Ihre Samen tragen ein fetthaltiges Anhängsel, das Ameisen anlockt — sie schleppen die Samen weg und verbreiten die Pflanze so ganz nebenbei</p><p>Trotz ihrer unauffälligen Erscheinung erreicht sie im Oberengadin Standorte bis auf über 2270 Meter Höhe</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lippenblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">herzförmig-gesägt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Wegränder, Hecken</td></tr></table>'),
('Matricaria chamomilla', 'Kamille', 'kraut', '<h3>Fun Facts</h3><p>Der Name geht auf das griechische Wort für "am Boden wachsender Apfel" zurück — passend dazu heißt sie im Deutschen auch "Apfelkraut"</p><p>1987 wurde sie zur ersten Arzneipflanze des Jahres gekürt, 2002 sogar noch einmal zur Heilpflanze des Jahres</p><p>In Italien gilt Kamillentee traditionell als Schlaf- und Beruhigungstee, besonders nach dem Essen oder vor dem Zubettgehen getrunken</p><p>Ihr ätherisches Öl ist tiefblau, obwohl die Blüten selbst gar keine blaue Farbe zeigen — die Farbe entsteht erst während der Herstellung aus einem eigentlich farblosen Vorläuferstoff</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß mit gelber Mitte</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">typisch aromatisch</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Äcker, Wegränder</td></tr></table>'),
('Mentha x piperita', 'Pfefferminze', 'kraut', '<h3>Fun Facts</h3><p>1696 entdeckte ein englischer Botaniker sie zufällig in einem Garten als Kreuzung aus Wasserminze und Grüner Minze — da letztere selbst schon eine Kreuzung ist, gilt sie als weitgehend steriler "Tripelbastard"</p><p>Weil sie kaum Samen bildet, lässt sie sich nur über Stecklinge sortenecht vermehren, nie zuverlässig aussäen</p><p>Das kühlende Gefühl bei Erkältungen wird zwar als angenehm empfunden, eine messbare abschwellende Wirkung ist aber wissenschaftlich nicht nachgewiesen</p><p>Ihr Mentholgehalt ist in älteren Blättern am höchsten — die beste Erntequalität liefert deshalb der Schnitt kurz vor der Blüte</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lippenblütler</td></tr><tr><td class="merkmal-key">Geruch/Geschmack</td><td class="merkmal-val">menthol-kühl</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">länglich-eiförmig, gezähnt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">feuchte Gärten, Beete</td></tr></table>'),
('Petroselinum crispum', 'Petersilie', 'kraut', '<h3>Fun Facts</h3><p>Galt im antiken Griechenland als heilig: In der Odyssee schmückt sie die Insel der Nymphe Kalypso, Sieger antiker Spiele erhielten Kränze daraus</p><p>Der Name bedeutet wörtlich "Steinsellerie" — über das Lateinische wurde daraus im Deutschen "Petersilie"</p><p>Nur 4 Gramm decken fast den gesamten Tagesbedarf an Vitamin K, doch ihre Samen sind giftig genug, dass sie 2023 zur "Giftpflanze des Jahres" gewählt wurde</p><p>Ihre Blätter verlieren beim Erhitzen schnell das typische Aroma, deshalb kommen sie meist roh oder erst ganz zum Schluss ins Essen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Doldenblütler</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">gefiedert, glatt oder kraus</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">typisch würzig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Gärten, Beete</td></tr></table>'),
('Salvia officinalis', 'Salbei', 'kraut', '<h3>Fun Facts</h3><p>Der Name geht auf das lateinische Wort für "heil, gesund" zurück — schon sprachlich wurde sie also direkt mit Heilung verbunden</p><p>Während einer Pestepidemie im 17. Jahrhundert rieben sich Plünderer angeblich mit einer Mischung aus Essig, Salbei, Thymian und Rosmarin ein, um sich zu schützen — die Stadt ließ sie für das vermeintliche Geheimnis am Leben</p><p>Ihre Blüten gelten als Spitzenreiter unter den Bienenweiden, der mögliche Honigertrag pro Hektar übertrifft laut manchen Quellen sogar den des Rapses</p><p>Karl der Große ordnete ihren Anbau ausdrücklich im Capitulare de villis an, und ein mittelalterliches Lehrgedicht führt sie an erster Stelle unter den Heilpflanzen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lippenblütler</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">länglich-oval, samtig</td></tr><tr><td class="merkmal-key">Behaarung</td><td class="merkmal-val">dicht, grau-filzig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">sonnige, steinige Gärten</td></tr></table>'),
('Salvia rosmarinus', 'Rosmarin', 'kraut', '<h3>Fun Facts</h3><p>Der Name bedeutet wörtlich "Tau des Meeres" — eine Deutung verweist auf die Küstenstandorte, an denen sich nachts Tau sammelt, eine ältere auf ein griechisches Wort für "balsamischer Strauch"</p><p>Er war Teil einer der frühesten destillierten Duftmischungen überhaupt, dem "Ungarischen Wasser" — die Legende versprach damit ewige Schönheit</p><p>Ein Extrakt davon ist heute als Lebensmittelzusatzstoff zugelassen und wirkt dort als natürliches Konservierungsmittel</p><p>Seine Früchte bleiben durch ölreiches Gewebe zusammenhängend, was Ameisen anlockt, die sie wegtragen und so ganz nebenbei verbreiten</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lippenblütler</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">nadelartig, immergrün</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">harzig-aromatisch</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">sonnig, mediterranes Klima</td></tr></table>'),
('Stellaria media', 'Vogelmiere', 'kraut', '<h3>Fun Facts</h3><p>Begleitet den Menschen schon seit der Steinzeit und gilt heute als echter Kosmopolit — nur in Australien fehlt sie bislang</p><p>Enthält laut Analysen etwa doppelt so viel Calcium und siebenmal so viel Eisen wie Kopfsalat, sollte wegen enthaltener Saponine aber nicht in großen Mengen gegessen werden</p><p>Ihre Blätter zeigen echte Schlafbewegungen: Bei trockenem Wetter öffnen sie sich morgens, bei feuchtem bleiben sie zusammengezogen</p><p>Eine feine Haarlinie entlang des Stängels leitet Tautropfen gezielt zum nächsten Blattpaar</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Nelkengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Anzahl Kronblätter</td><td class="merkmal-val">5, tief gespalten</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Äcker, Gärten</td></tr></table>'),
('Thymus vulgaris', 'Thymian', 'kraut', '<h3>Fun Facts</h3><p>2006 zur Arzneipflanze des Jahres gewählt — das ätherische Öl ist offiziell anerkannt bei Erkrankungen der oberen Atemwege und wirkt im Labor nachweislich antibakteriell</p><p>Tritt in sechs verschiedenen chemischen Typen auf, die je nach genetischen und klimatischen Bedingungen unterschiedliche Hauptwirkstoffe in ihrem ätherischen Öl bilden</p><p>Auf einem Hektar können Bienen pro Saison bis zu 185 kg Honig aus seinen Blüten gewinnen</p><p>Schon der römische Gelehrte Plinius erwähnte die Pflanze, später tauchte sie auch in den Schriften Hildegards von Bingen auf</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Lippenblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß bis rosa</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">würzig-aromatisch</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">trockene, steinige Böden</td></tr></table>'),
('Urtica dioica', 'Brennnessel', 'kraut', '<h3>Fun Facts</h3><p>Ihre Brennhaare sind mit Kieselsäure verstärkt und spritzen beim Abbrechen einen Cocktail aus Histamin, Acetylcholin und Serotonin — daher das brennende Gefühl</p><p>Trocknen, Kochen oder kräftiges Kneten nehmen den Blättern die stechende Wirkung — danach lassen sie sich wie Spinat zubereiten</p><p>Bis ins 18. Jahrhundert war sie eine wichtige Faserpflanze, ihre reißfesten, feuchtigkeitsaufnehmenden Fasern wurden zu Textilien verarbeitet</p><p>Der Kleine Fuchs, ein heimischer Schmetterling, ernährt sich als Raupe fast ausschließlich von ihr</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Brennnesselgewächse</td></tr><tr><td class="merkmal-key">Behaarung</td><td class="merkmal-val">Brennhaare</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">herzförmig-gesägt</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">nährstoffreiche Böden, Wegränder</td></tr></table>'),
('Dianthus caryophyllus', 'Garten-Nelke', 'garten', '<h3>Fun Facts</h3><p>Der Artname geht auf das griechische Wort für Gewürznelke zurück, und auch der deutsche Name "Nelke" stammt aus dem Mittelhochdeutschen für genau dieses Gewürz</p><p>In Oxford tragen Studierende traditionell Nelken zu Prüfungen: weiß zur ersten, rosa zu den mittleren, rot zur letzten Prüfung</p><p>In Südchina werden getrocknete, ganze Blüten zu Tee verarbeitet — in warmem Wasser scheint sich die Blüte dabei noch einmal zu öffnen</p><p>Wild kommt sie ursprünglich nur im Mittelmeerraum vor, etwa in Griechenland, Italien, Sizilien und Sardinien, an warmen, sonnigen Standorten</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Nelkengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">rosa bis rot, 5 Kronblätter</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">würzig-süß</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">sonnig, warme Lagen</td></tr></table>'),
('Forsythia x intermedia', 'Forsythie', 'garten', '<h3>Fun Facts</h3><p>Die Gattung ehrt den britischen königlichen Gärtner William Forsyth und ist selbst eine Kreuzung zweier ostasiatischer Arten</p><p>Viele ihrer Blüten sind steril und bieten weder Pollen noch Nektar — für Wildbienen und Schmetterlinge sind sie trotz der auffälligen Farbe weitgehend wertlos</p><p>Ihre Blüten kommen in zwei verschiedenen Formen auf unterschiedlichen Pflanzen vor — ein Rätsel, das schon Charles Darwin beschäftigte</p><p>Sie blüht bereits im zeitigen Frühjahr, noch bevor die Blätter austreiben, direkt an den kahlen Zweigen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Ölbaumgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">leuchtend gelb</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Gärten, Parks, Ziergehölz</td></tr></table>'),
('Helianthus annuus', 'Sonnenblume', 'garten', '<h3>Fun Facts</h3><p>Archäologische Funde deuten darauf hin, dass sie schon um 2500 v. Chr. im Mississippi-Gebiet angebaut wurde — die Inka verehrten sie sogar als Abbild ihres Sonnengottes</p><p>Spanische Seefahrer brachten die Samen 1552 nach Europa, wo sie zunächst nur als Zierpflanze in Gärten wuchs — erst seit dem 19. Jahrhundert wird sie als Ölpflanze genutzt</p><p>Heute ist sie weltweit die drittgrößte Ölpflanze nach Sojabohne und Raps</p><p>Junge Knospen folgen dem Sonnenstand von Ost nach West, sobald die Pflanze blüht, bleibt der Kopf meist nach Osten gerichtet — daher auch der Beiname "Kompasspflanze"</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">gelb mit dunkler Mitte</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">sonnige Gärten, nährstoffreiche Böden</td></tr></table>'),
('Hydrangea macrophylla', 'Garten-Hortensie', 'garten', '<h3>Fun Facts</h3><p>Ihr Farbstoff Delphinidin ist in saurem Boden violett bis blau, in alkalischem Boden dagegen rot — Aluminiumionen im Boden verstärken die Blaufärbung zusätzlich</p><p>Der deutsche Name stammt von Hortense de Nassau, der Tochter eines Teilnehmers einer Südsee-Expedition im 18. Jahrhundert</p><p>Erstbeschrieben wurde sie 1784 von einem schwedischen Arzt, der sich damals in Japan aufhielt — zunächst allerdings unter einem völlig anderen Gattungsnamen</p><p>Die Blütenknospen für das nächste Jahr werden bereits im Spätsommer angelegt, wer im Herbst zurückschneidet, riskiert im Folgejahr blütenlose Pflanzen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Hortensiengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß, blau oder rosa, pH-abhängig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">halbschattig, feucht, saurer Boden</td></tr></table>'),
('Lilium candidum', 'Madonnenlilie', 'garten', '<h3>Fun Facts</h3><p>Zählt zu den ältesten Zierpflanzen der Menschheit: Vasen von Santorini aus der Zeit um 1500 v. Chr. zeigen sie vermutlich als Schnittblume, auch assyrische Reliefs bilden sie ab</p><p>Der Artname bedeutet "strahlend weiß" — ihre spätere Rolle als christliches Reinheitssymbol gab ihr erst den deutschen Namen</p><p>Wegen dieser Symbolik malte man sie in der christlichen Kunst oft ganz ohne Staubgefäße oder Griffel, etwa in Darstellungen der Verkündigung an Maria</p><p>Anders als bei den meisten anderen Lilienarten sitzt ihre Zwiebel nur knapp unter der Bodenoberfläche</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Liliengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">rein weiß</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">intensiv-süß</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">trockene, lehmige Böden, sonnig</td></tr></table>'),
('Pelargonium zonale', 'Garten-Pelargonie', 'garten', '<h3>Fun Facts</h3><p>Im Alltag "Geranie" genannt, ist aber botanisch gar nicht mit dem echten Storchschnabel (Geranium) verwandt — der Gattungsname kommt vom griechischen Wort für Storch, der Trivialname fälschlich vom Wort für Kranich</p><p>Lange Zeit ordneten Botaniker sie der Gattung Geranium zu, erst 1789 wurde die eigene Gattung Pelargonium offiziell etabliert</p><p>Um 1600 kamen die ersten Exemplare aus Südafrika nach Europa und wurden fast 200 Jahre lang zu Stars der höfischen Orangerien, manche Sammlungen umfassten hunderte Sorten</p><p>Eine verwandte Art, die Rosengeranie, liefert ein stark duftendes Öl, das bis heute in der Parfümindustrie verwendet wird</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Storchschnabelgewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">nahezu kreisrund</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Balkonkästen, sonnig</td></tr></table>'),
('Rosa canina', 'Hundsrose', 'garten', '<h3>Fun Facts</h3><p>Der Name war vermutlich leicht abwertend gemeint — "Hunds-" steht in deutschen Pflanzennamen oft für "die gewöhnliche" Art, eine andere Deutung verweist auf den alten Glauben, die Wurzel helfe gegen Tollwut</p><p>Rosenschulen veredeln bis heute viele Zuchtrosen auf ihre kräftigen Wurzeln — sie ist damit die wichtigste Unterlage im Rosenanbau</p><p>Einzelne Sträucher werden bis zu 300 Jahre alt, bekanntestes Beispiel ist der "Tausendjährige Rosenstock" am Hildesheimer Dom</p><p>Gallwespen legen Eier in ihre Triebe, wodurch das Pflanzengewebe zu kugeligen "Rosenäpfeln" auswuchert, in denen die Larven heranwachsen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Rosengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">hellrosa</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">rote Hagebutte</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Hecken, Weg- und Waldränder</td></tr></table>'),
('Syringa vulgaris', 'Flieder', 'garten', '<h3>Fun Facts</h3><p>Seine Heimat liegt in Südosteuropa, etwa in Bulgarien, Griechenland, Rumänien und Albanien — erst später wurde er in ganz Europa zum beliebten Zierstrauch</p><p>Bei Trockenheit nagen Hornissen und Wespen an seiner Rinde, um an den Pflanzensaft zu gelangen — dieses Verhalten nennt man "Ringeln"</p><p>In Deutschland schmückt seine Blüte am Vatertag traditionell die Ausflugswagen und Hemden der Männer bei ihren Herrentagspartien</p><p>Trotz des ähnlichen Namens ist er nicht mit dem Sommerflieder (Buddleja) verwandt, der zu einer ganz anderen Pflanzenfamilie gehört</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Ölbaumgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">violett oder weiß</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">intensiv-süß</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Gärten, Parks, Hecken</td></tr></table>'),
('Tagetes patula', 'Studentenblume', 'garten', '<h3>Fun Facts</h3><p>Der Gattungsname ehrt Tages, eine etruskische Gottheit — stammt ursprünglich aus Mexiko, hat sich aber inzwischen von Kuba bis zu den Philippinen eingebürgert</p><p>Als Beetnachbar soll ihr strenger Duft Schädlinge wie Weiße Fliegen fernhalten, als Gründüngung hilft sie sogar gegen bodenmüde machende Fadenwürmer</p><p>Ihre Blüten enthalten das gelbe Pigment Lutein, das als Lebensmittelfarbstoff und zur Gelbfärbung von Eigelb im Hühnerfutter genutzt wird — China liefert rund die Hälfte des Weltbedarfs</p><p>Ältere Sorten haben einen intensiven, von vielen als unangenehm empfundenen Duft, neuere Züchtungen wurden gezielt darauf hin verändert, kaum noch zu riechen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Korbblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">zitronengelb bis rotbraun</td></tr><tr><td class="merkmal-key">Geruch</td><td class="merkmal-val">herb-würzig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">sonnig, anspruchslos</td></tr></table>'),
('Tulipa gesneriana', 'Tulpe', 'garten', '<h3>Fun Facts</h3><p>Ihr Name stammt vom persischen Wort für "Herz binden", gelangte über das Türkische nach Europa — nach anderer Deutung geht er auf das osmanische Wort für Turban zurück, an den die Blütenform erinnert</p><p>Im 17. Jahrhundert lösten einzelne Zwiebeln eine regelrechte Spekulationsblase aus, bis sich ihr Handelswert nach einem Börsenkrach 1637 wieder normalisierte</p><p>Im niederländischen Hungerwinter 1944/45 erklärten Ärzte die stärkereichen Zwiebeln für essbar — sie wurden damals verkauft und nach eigenen Rezepten zubereitet</p><p>Über 80% der weltweiten Produktion stammen heute aus den Niederlanden, obwohl ihre Wildvorfahren ursprünglich aus dem Mittleren Osten kommen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Liliengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">vielfärbig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">nährstoffreich, feucht im Frühjahr</td></tr></table>'),
('Aconitum napellus', 'Blauer Eisenhut', 'gift', '<h3>Fun Facts</h3><p>Gilt als die giftigste Pflanzenart Europas — schon kleinste Mengen können gefährliche Vergiftungserscheinungen auslösen, Hautkontakt reicht bei manchen Menschen bereits aus</p><p>Einer griechischen Sage zufolge wuchs sie aus dem Speichel des Höllenhunds Kerberos, den Herakles aus der Unterwelt gezogen hatte</p><p>Ein Arzt im 16. Jahrhundert soll zum Tode Verurteilten erst das Gift und dann ein Gegenmittel verabreicht haben — wer überlebte, kam frei</p><p>Samuel Hahnemann testete die Wirkung im 19. Jahrhundert an sich und seiner Familie und legte damit den Grundstein für ihren Einsatz in der Homöopathie</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Hahnenfußgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">tiefblau-violett</td></tr><tr><td class="merkmal-key">Blütenform</td><td class="merkmal-val">helmartig, zygomorph</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">feuchte Bergwiesen, Bachufer</td></tr></table>'),
('Atropa belladonna', 'Tollkirsche', 'gift', '<h3>Fun Facts</h3><p>Die Gattung ist nach Atropos benannt, einer der drei Schicksalsgöttinnen der griechischen Mythologie, die den Lebensfaden durchtrennt — ein passender Name für eine der giftigsten heimischen Pflanzen</p><p>Der Artname "belladonna" (schöne Frau) geht auf die frühere Mode zurück, sich Extrakttropfen in die Augen zu geben, weil sie die Pupillen weit und damit ausdrucksvoller erscheinen lassen</p><p>Alle Pflanzenteile enthalten große Mengen giftiger Alkaloide, vor allem Hyoscyamin, das sich im Körper teilweise zu Atropin umwandelt</p><p>Eine einzige Beere kann bis zu 160 winzige Samen enthalten — trotz ihres süßlichen Geschmacks bleibt sie hochgiftig</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Nachtschattengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">braun-violett, glockig</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">schwarze Beere, giftig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Waldlichtungen, Schuttplätze</td></tr></table>'),
('Colchicum autumnale', 'Herbstzeitlose', 'gift', '<h3>Fun Facts</h3><p>Der Gattungsname verweist auf Kolchis am Schwarzen Meer, die sagenhafte Heimat der Giftmischerin Medea aus der griechischen Mythologie</p><p>Blüte und Blätter erscheinen nie gemeinsam: Im Herbst sieht man nur die Blüten ohne Blätter, im Frühjahr nur die Blätter ohne Blüten</p><p>Ihre Blätter werden oft mit dem essbaren Bärlauch verwechselt — anders als dessen dünne, schlaffe Blätter sind ihre aber dick, steif und leicht nach links gedreht, die Verwechslung endete schon tödlich</p><p>Ihr Gift Colchicin wird trotz seiner Giftigkeit medizinisch bei akuten Gichtanfällen eingesetzt und von Pflanzenzüchtern genutzt, um durch Chromosomenverdopplung etwa größere Erdbeeren zu erzeugen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Zeitlosengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">hellviolett bis rosa</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">feuchte, nährstoffreiche Wiesen</td></tr></table>'),
('Convallaria majalis', 'Maiglöckchen', 'gift', '<h3>Fun Facts</h3><p>In Frankreich verschenkt man am 1. Mai Sträußchen davon an Freunde, ein Brauch, der laut Legende auf eine Idee des französischen Königs Karl IX. aus dem Jahr 1560 zurückgeht</p><p>Alle Pflanzenteile sind giftig, allein die herzwirksamen Glykoside in Blüten und Beeren können bei Verwechslung mit Bärlauch gefährlich werden — unterscheiden lässt sich das am Geruch, Bärlauch riecht deutlich nach Knoblauch</p><p>Der Astronom Nikolaus Kopernikus ließ sich einst mit dieser Pflanze in der Hand porträtieren, als Symbol der Heilkunst</p><p>Im 19. Jahrhundert wurde es als milderer Ersatz für den Fingerhut bei Herzschwäche medizinisch eingesetzt</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Spargelgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß, glockig</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">rote Beere, giftig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">halbschattige Laubwälder</td></tr></table>'),
('Datura stramonium', 'Stechapfel', 'gift', '<h3>Fun Facts</h3><p>Der Name gelangte über das Portugiesische aus dem Hindi nach Europa, belegt ist er schon im Sanskrit — der deutsche Name "Stechapfel" verweist auf die stachelige Fruchtkapsel</p><p>Obwohl heute weltweit verbreitet, ist ihre ursprüngliche Heimat gar nicht sicher bekannt</p><p>1762 testete der Leibarzt der Kaiserin Maria Theresia einen Extrakt der ganzen Pflanze zunächst an sich selbst, bevor er ihn bei Patienten einsetzte — die medizinische Nutzung setzte sich danach nur langsam durch</p><p>Ein Asteroid trägt sogar ihren Gattungsnamen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Nachtschattengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß, trichterförmig</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">stachelige Kapsel</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Äcker, Schuttplätze</td></tr></table>'),
('Digitalis purpurea', 'Roter Fingerhut', 'gift', '<h3>Fun Facts</h3><p>Der Name geht auf das lateinische Wort für Finger zurück, wegen der fingerhutförmigen Blüten — Volksnamen wie "Marienglöckchen" verweisen auf dieselbe Form</p><p>Ein englischer Arzt nutzte 1775 ein altes Familienrezept, um damit Wassereinlagerungen durch Herzschwäche zu behandeln — seine Veröffentlichung von 1785 machte die Pflanze zum Grundstein der modernen Herzmedizin</p><p>Alle Pflanzenteile sind hochgiftig, schon kleine Mengen können gefährlich werden, erste Warnzeichen einer Vergiftung sind Übelkeit und ein sehr langsamer Puls</p><p>Die dunklen Flecken im Blüteninneren galten lange als Nektar-Wegweiser für Insekten — deckte man sie ab, wurden die Blüten nur noch ein Fünftel so oft angeflogen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Wegerichgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">purpurrosa</td></tr><tr><td class="merkmal-key">Blütenform</td><td class="merkmal-val">fingerhutartig, glockig</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Waldlichtungen, Schonungen</td></tr></table>'),
('Heracleum mantegazzianum', 'Riesen-Bärenklau', 'gift', '<h3>Fun Facts</h3><p>Auch Herkulesstaude genannt, stammt sie ursprünglich aus dem Westkaukasus, wo sie bis in 2200 Meter Höhe oberhalb der Waldgrenze wächst — nach Europa kam sie erst im 19. Jahrhundert</p><p>Schon Hautkontakt kann bei Sonnenlicht Blasen verursachen, die wie Verbrennungen aussehen — dünne Einmalhandschuhe werden nach etwa einer Stunde bereits durchdrungen</p><p>Eine einzelne Pflanze kann bis zu 80.000 Einzelblüten und 15.000 Früchte bilden, die über mehrere Jahre keimfähig bleiben</p><p>In der zweiten Hälfte des 20. Jahrhunderts empfahl man sie Imkern sogar als Bienenweide, besucht wird ihr Nektar aber überwiegend von anderen Insekten als der Honigbiene</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Doldenblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Blütenform</td><td class="merkmal-val">große Doppeldolde, 30-50 cm</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Flussufer, Brachen, Waldränder</td></tr></table>'),
('Laburnum anagyroides', 'Goldregen', 'gift', '<h3>Fun Facts</h3><p>Trägt auch den Namen "Bohnenbaum" wegen seiner bohnenartigen Hülsen — die Forsythie wird im Volksmund oft fälschlich ebenfalls Goldregen genannt, ist botanisch aber eine ganz andere Pflanze</p><p>Alle Teile enthalten das Gift Cytisin, am stärksten in den Samen — schon wenige Hülsen können für Kinder gefährlich werden</p><p>Ausgerechnet dieser nikotinähnliche Stoff findet sich heute in Präparaten zur Raucherentwöhnung, da er selbst kaum Suchtpotenzial haben soll</p><p>Ursprünglich aus Süd- und Südosteuropa, wird er seit Jahrhunderten als Zierpflanze kultiviert und findet sich in Mitteleuropa fast nur in Gärten und Parks</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Schmetterlingsblütler</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">leuchtend gelb</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">giftige Hülse mit Samen</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Gärten, Parks</td></tr></table>'),
('Corylus avellana', 'Gemeine Hasel', 'strauch', '<h3>Fun Facts</h3><p>Ein einziges männliches Kätzchen enthält rund 2 Millionen Pollenkörner — sie blüht schon im Februar oder März, lange vor dem Laubaustrieb</p><p>Nach der letzten Eiszeit war sie zwischen 7000 und 6000 v. Chr. das vorherrschende Gehölz in Mitteleuropa — manche Forscher bringen ihre schnelle Ausbreitung mit Menschen in Verbindung, die Nussvorräte anlegten</p><p>Die meisten im Handel erhältlichen Haselnüsse stammen gar nicht von dieser Art, sondern von einer eng verwandten Kulturform, hauptsächlich angebaut an der türkischen Schwarzmeerküste</p><p>Der Artname verweist auf die antike Stadt Abella bei Neapel, die schon in der Antike für ihren Haselnussanbau bekannt war</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Birkengewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">rundlich, gezähnt</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">Haselnuss</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Hecken, Waldränder</td></tr></table>'),
('Crataegus monogyna', 'Eingriffeliger Weißdorn', 'strauch', '<h3>Fun Facts</h3><p>Der Gattungsname bedeutet "stark, kräftig" und spielt auf seine Heilkraft an — Zubereitungen daraus werden bis heute bei leichter Herzschwäche eingesetzt</p><p>In Notzeiten wurde das getrocknete Fruchtfleisch zu "Mehlbeeren"-Mehl gemahlen, die Blätter dienten als Teeersatz und die Samen gemahlen sogar als Kaffeeersatz</p><p>Trägt weit über hundert deutsche Volksnamen — der Blütenduft erinnert aus der Nähe eher an Maikäfer als an klassischen Blütenduft, bestäubt wird er daher vor allem von Fliegen</p><p>Namensgebend für den Artnamen ist der einzelne Griffel in jeder Blüte, der ihn von verwandten Arten mit mehreren Griffeln unterscheidet</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Rosengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">rote Steinfrucht</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Hecken, Waldränder</td></tr></table>'),
('Prunus spinosa', 'Schlehe', 'strauch', '<h3>Fun Facts</h3><p>Erst Frost baut einen Teil der bitteren Gerbstoffe ab, deshalb schmecken die Früchte wirklich erst nach dem ersten Frost milder</p><p>Im Pfahlbaudorf Sipplingen am Bodensee fanden sich um 3300 v. Chr. durchlochte Kerne dieser Pflanze, vermutlich als Kette getragen</p><p>Im Mittelalter gewann man aus ihrer Rinde eine Tinte für Schreibstuben — ein langwieriges Verfahren, das später ganz in Vergessenheit geriet</p><p>Das slawische Wort für sie bedeutet eigentlich "Zwetschge" und ist auch der Ursprung des Wortes "Sliwowitz"</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Rosengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">blauschwarze Steinfrucht</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Hecken, Feldränder</td></tr></table>'),
('Rubus fruticosus', 'Brombeere', 'strauch', '<h3>Fun Facts</h3><p>Was wie eine Beere aussieht, ist botanisch eine Sammelsteinfrucht: jedes der kleinen Kügelchen enthält einen eigenen Stein mit Samen</p><p>Die meisten Arten sind tetraploide Hybriden, die sich ohne Befruchtung der Eizelle vermehren — praktisch jede Pflanze ist genetisch ein Klon ihrer Art</p><p>Mit ihren rückwärts gerichteten Stacheln sind sie "Spreizklimmer" und können an geeigneten Standorten bis zu 5 Meter in Bäume hinaufklettern</p><p>Die Blätter enthalten Gerbstoffe und wirken adstringierend — fermentiert ergeben sie einen koffeinfreien Tee, der traditionell gegen Durchfall genutzt wird</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Rosengewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">weiß, selten rosa</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">unpaarig gefiedert, 3-7 gezähnte Teilblättchen</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">blauschwarze Sammelsteinfrucht</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">lichte Wälder, Waldränder, kalk- und stickstoffreiche Böden</td></tr></table>'),
('Sambucus nigra', 'Schwarzer Holunder', 'strauch', '<h3>Fun Facts</h3><p>Trug ursprünglich selbst den Namen "Flieder" — erst ab dem 16. Jahrhundert wanderte dieser Name auf den neu aus Südosteuropa eingeführten Zierstrauch Syringa</p><p>Im Volksglauben galt er als Lebensbaum, der vor Hexen und Blitz schützen sollte — ihn zu fällen brachte angeblich Unglück, man zog vor ihm sogar den Hut</p><p>Einer Legende nach soll sich Judas an einem solchen Baum erhängt haben, was den eigenwilligen Geruch der frischen Blätter erklären soll</p><p>Trotz insektenfreundlicher Blüten bestäubt er sich überdurchschnittlich oft selbst, statt auf Insekten zu warten</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Moschuskrautgewächse</td></tr><tr><td class="merkmal-key">Blütenfarbe</td><td class="merkmal-val">cremeweiß</td></tr><tr><td class="merkmal-key">Frucht</td><td class="merkmal-val">schwarze Beere</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">Hecken, Waldränder</td></tr></table>'),
('Dryopteris filix-mas', 'Gemeiner Wurmfarn', 'farn', '<h3>Fun Facts</h3><p>Schon 1543 unterschied der Botaniker Leonhart Fuchs ein "Männlein" und ein "Weiblein" dieser Farnfamilie — daher der Gegenpart Frauenfarn</p><p>Der giftige Wurzelstock wurde früher in der Tiermedizin gegen Wurmbefall eingesetzt, konnte in höherer Dosis aber selbst Schafe töten</p><p>Weil Farne nie blühen, glaubte man früher, sie täten es heimlich in der Johannisnacht — wer den "Farnsamen" fände, werde unsichtbar</p><p>Von der ersten Anlage am Rhizom bis zum voll entfalteten Wedel vergehen mehrere Jahre, das Rhizom speichert dafür Öl und Zucker als Reserve</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Wurmfarngewächse</td></tr><tr><td class="merkmal-key">Wuchshöhe</td><td class="merkmal-val">30-120 cm, trichterförmige Rosette</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">zweifach gefiedert, bis 140 cm lang</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">frische Laub- und Nadelwälder, Gebüsche, Mauern</td></tr></table>'),
('Pteridium aquilinum', 'Adlerfarn', 'farn', '<h3>Fun Facts</h3><p>In Finnland wurden unterirdische Rhizome von bis zu 60 Metern Länge entdeckt, geschätzt rund 1500 Jahre alt</p><p>Die jungen, eingerollten Blattknospen werden wegen ihrer Form oft "Fiedelköpfe" genannt, nach der Schnecke einer Geige</p><p>Im Mittelalter glaubte man, Farne blühten heimlich in der Walpurgisnacht und ihre "Samen" machten denjenigen unsichtbar, der sie fände</p><p>Obwohl giftige Stoffe enthalten sind, wird er in Teilen Asiens seit rund 3000 Jahren gegessen — in Japan erst stundenlang in heißer Natronlauge eingelegt, um ihn verträglicher zu machen</p><h3>Bestimmungsmerkmale</h3><table class="merkmale-table"><tr><td class="merkmal-key">Pflanzenfamilie</td><td class="merkmal-val">Adlerfarngewächse</td></tr><tr><td class="merkmal-key">Blattform</td><td class="merkmal-val">3-4fach gefiedert, bis 2 m hoch</td></tr><tr><td class="merkmal-key">Standort</td><td class="merkmal-val">lichte Wälder, Waldränder, saure Böden</td></tr></table>');
